-- Book stock: each close is the last close plus receipts, minus sales and write-offs, plus count adjustments
WITH days AS (SELECT DISTINCT date FROM {{ ref('inventory_book') }}), rcv AS (SELECT date, sku, sum(u) AS u FROM ( SELECT CAST(received_ts AS DATE) AS date, sku_booked AS sku, units_booked AS u FROM {{ ref('goods_receipts') }} UNION ALL SELECT CAST(delivery_ts AS DATE), sku, units FROM {{ ref('fresh_deliveries') }}) GROUP BY ALL), sold AS (SELECT CAST(bill_ts AS DATE) AS date, sku_scanned AS sku, sum(qty) AS u FROM {{ ref('pos_lines') }} GROUP BY ALL), wo AS (SELECT date, sku, sum(units) AS u FROM {{ ref('write_offs') }} GROUP BY ALL), adj AS (SELECT CAST(count_ts AS DATE) AS date, sku, sum(adjustment) AS u FROM {{ ref('stock_counts') }} WHERE hour(count_ts) < 22 GROUP BY ALL) SELECT b.date, b.sku, b.book_on_hand_close AS book, prev.book_on_hand_close + coalesce(rcv.u, 0) - coalesce(sold.u, 0) - coalesce(wo.u, 0) + coalesce(adj.u, 0) AS rebuilt FROM {{ ref('inventory_book') }} b JOIN {{ ref('inventory_book') }} prev ON prev.sku = b.sku AND prev.date = b.date - 1 LEFT JOIN rcv ON rcv.date = b.date AND rcv.sku = b.sku LEFT JOIN sold ON sold.date = b.date AND sold.sku = b.sku LEFT JOIN wo ON wo.date = b.date AND wo.sku = b.sku LEFT JOIN adj ON adj.date = b.date AND adj.sku = b.sku WHERE book <> rebuilt
